def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    row_lines = [r for r in range(h) if sum(x == 2 for x in grid[r]) >= 0.65 * w]
    col_lines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= 0.65 * h]
    horizontal = bool(row_lines) and (
        not col_lines or
        max(sum(x == 2 for x in grid[r]) / w for r in row_lines) >=
        max(sum(grid[r][c] == 2 for r in range(h)) / h for c in col_lines)
    )
    lines = row_lines if horizontal else col_lines

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == (2 if (rr, cc) == (r, c) else 3)
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
            ):
                centers.append((r, c))

    source_cells = {
        (rr, cc)
        for r, c in centers
        for rr in range(r - 1, r + 2)
        for cc in range(c - 1, c + 2)
    }

    for r, c in centers:
        if horizontal:
            for rr in range(h):
                if out[rr][c] == 0:
                    out[rr][c] = 1
            targets = [(line, c) for line in lines if line != r]
        else:
            for cc in range(w):
                if out[r][cc] == 0:
                    out[r][cc] = 1
            targets = [(r, line) for line in lines if line != c]

        for tr, tc in targets:
            for rr in range(max(0, tr - 1), min(h, tr + 2)):
                for cc in range(max(0, tc - 1), min(w, tc + 2)):
                    if (rr, cc) in source_cells:
                        continue
                    out[rr][cc] = 2 if (rr, cc) == (tr, tc) else 1

    return out
